 57: 
 58:   private async loadAutoSyncSettings(): Promise<void> {
 59:     try {
 60:       const enabled = await this.webdavStateStore.getAutoSyncEnabled();
 61:       const hours = await this.webdavStateStore.getAutoSyncIntervalHours();
 62:       const uploadModel = await this.webdavStateStore.getAutoSyncUploadModelEnabled();
 63:       const uploadBackup = await this.webdavStateStore.getAutoSyncUploadBackupEnabled();
 64:       const lastSuccess = await this.webdavStateStore.getAutoSyncLastSuccessMs();
