176: 
177:     // 第一层确认：点击按钮后立即弹出，防止误触
178:     try {
179:       const firstConfirm = await promptAction.showDialog({
180:         title: '从云端恢复',
181:         message: '⚠️ 警告：此操作将从云端下载备份并覆盖本地数据，本地未同步的学习记录将丢失。\n\n确定要继续吗？',
