222:         return;
223:       }
224: 
225:       // Step 2: Parse and preview backup data
226:       this.webdavBackupResult = '正在解析备份数据...';
227:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
228:       
229:       const preview = await this.syncManager.previewImport(download.plain);
