232:         promptAction.showToast({ message: '预览失败', duration: 1200 });
233:         this.webdavBusy = false;
234:         this.restoreDialogShowing = false;
235:         return;
236:       }
237: 
238:       // Release busy state while waiting for user confirmation
239:       this.webdavBusy = false;
240:       this.webdavBackupResult = ''; // Clear loading message before showing dialog
241: 
242:       // Step 3: Show second confirmation dialog with preview data
243:       const sample = preview.sampleUpdatedWords.length > 0 ? `\n示例：${preview.sampleUpdatedWords.join('、')}` : '';
244:       const msg = `⚠️ 警告：此操作将覆盖本地数据！\n\n将覆盖更新 ${preview.updated} 词，新增 ${preview.imported} 词，共 ${preview.total} 词。${sample}\n\n本地未同步的学习记录将丢失，请确认是否继续？`;
245: 
246:       let userConfirmed = false;
