204:     this.webdavAutoSyncIntervalIndex = idx >= 0 ? idx : 2;
205:     this.webdavAutoSyncUploadModelEnabled = await this.webdavStateStore.getAutoSyncUploadModelEnabled();
206:     this.webdavAutoSyncUploadBackupEnabled = await this.webdavStateStore.getAutoSyncUploadBackupEnabled();
