211:   private async loadSettings(): Promise<void> {
212:     try {
213:       const secureStorage = SecureStorage.getInstance();
214:       this.apiKey = await secureStorage.getApiKey();
215:       
216:       const settingsStore = SettingsStore.getInstance();
217:       const persisted = await settingsStore.getSettings();
218:       
219:       let settings = persisted;
220:       if (!settings) {
221:         const settingsJson = AppStorage.get<string>(this.STORAGE_KEY_SETTINGS);
222:         if (settingsJson && settingsJson.length > 0) {
223:           settings = AppSettings.fromJSON(settingsJson);
224:           await settingsStore.saveSettings(settings);
225:         }
226:       }
227: 
228:       if (settings) {
229:         if (!persisted) { // If loaded from AppStorage, sync to AppStorage again? No, just load vars
230:            AppStorage.setOrCreate(this.STORAGE_KEY_SETTINGS, settings.toJSON());
231:         } else {
232:            AppStorage.setOrCreate(this.STORAGE_KEY_SETTINGS, settings.toJSON());
233:         }
234:         
235:         this.apiBaseUrl = settings.apiBaseUrl;
236:         this.selectedModel = settings.apiModel;
237:         this.selectedContextStyle = settings.contextStyle as ContextStyle;
238:         this.customContextStyle = settings.customContextStyle;
239:         this.selectedDifficultyLevel = settings.difficultyLevel as DifficultyLevel;
240:         this.dailyNewWords = settings.dailyNewWords;
241:         this.dailyTotalTasks = settings.dailyTotalTasks;
242:         this.dailyReviewWords = settings.dailyReviewWords;
243:         this.studyFlowMode = settings.studyFlowMode;
244:         this.learningOrderPolicy = this.parseLearningOrderPolicy(settings.toJSON());
245:         this.enableTTS = settings.enableTTS;
246:         this.pronunciationMode = settings.pronunciationMode;
247:         this.newbieMode = settings.newbieMode;
248:         this.themeId = settings.theme ?? 'light';
249:         ThemeManager.getInstance().setTheme(this.themeId);
250:         this.contextLengthMin = settings.contextLengthMin;
251:         this.contextLengthMax = settings.contextLengthMax;
252:         this.learningStepMinutes = settings.learningStepMinutes.length > 0
253:           ? settings.learningStepMinutes
254:           : [5, 120];
255:         this.enableVignetteCache = settings.enableVignetteCache;
256:         this.vignetteCacheMaxMB = Math.max(1, Math.round(settings.vignetteCacheMaxBytes / 1_000_000));
