270:     const normalized = this.normalizeApiBaseUrl(url);
271:     for (let i = 0; i < API_PROVIDERS.length - 1; i++) {
272:       const providerUrl = this.normalizeApiBaseUrl(API_PROVIDERS[i].baseUrl);
273:       if (providerUrl === normalized) {
274:         this.selectedProviderIndex = i;
275:         const models = API_PROVIDERS[i].models;
276:         if (models.length > 0 && models.indexOf(this.selectedModel) < 0) {
277:           this.selectedModel = models[0];
