285:   private normalizeApiBaseUrl(url: string): string {
286:     let base = url.trim();
287:     while (base.endsWith('/')) {
288:       base = base.slice(0, base.length - 1);
289:     }
290:     const versionPaths = ['/v1', '/v2', '/v4', '/api/v3', '/compatible-mode/v1'];
291:     for (const path of versionPaths) {
292:       if (base.endsWith(path)) {
293:         base = base.slice(0, base.length - path.length);
294:         break;
295:       }
296:     }
297:     return base;
298:   }
