 19:   async backupToCloud(
 20:     client: IWebDavBackend,
 21:     settings: WebDavSettings,
 22:     manifest: WebDavManifest,
 23:     remoteFile: string
 24:   ): Promise<WebDavSyncResult> {
 25:     const exportStartMs = Date.now();
 26:     const exportResult = await this.syncManager.exportData();
 27:     const exportElapsedMs = Date.now() - exportStartMs;
 28:     console.info(`[WebDAV] backup export ms=${exportElapsedMs}`);
 29:     if (!exportResult.success) {
 30:       return WebDavSyncResult.fail('导出失败', exportResult.error);
 31:     }
 32: 
 33:     await new Promise<void>((resolve) => setTimeout(resolve, 50));
 34: 
 35:     const dataSize = exportResult.data.length;
 36:     console.info(`[WebDAV] backup data size=${dataSize}`);
 37:     
 38:     if (dataSize > 5 * 1024 * 1024) {
 39:       console.warn(`[WebDAV] backup data too large: ${dataSize} bytes`);
 40:     }
 41: 
 42:     await new Promise<void>((resolve) => setTimeout(resolve, 0));
 43: 
 44:     const encStartMs = Date.now();
 45:     const enc = await WebDavCrypto.encryptUtf8Offloaded(exportResult.data, settings.syncPassword);
 46:     const encElapsedMs = Date.now() - encStartMs;
 47:     console.info(`[WebDAV] backup encrypt ms=${encElapsedMs}`);
 48:     
 49:     await new Promise<void>((resolve) => setTimeout(resolve, 50));
 50:     
 51:     const putStartMs = Date.now();
 52:     const putRes = await client.put(remoteFile, enc, 'application/json');
 53:     const putElapsedMs = Date.now() - putStartMs;
 54:     console.info(`[WebDAV] backup put status=${putRes.statusCode} ms=${putElapsedMs}`);
 55:     
 56:     if (putRes.statusCode < 200 || putRes.statusCode >= 300) {
 57:       return WebDavSyncResult.fail('上传失败', `PUT ${putRes.statusCode}: ${putRes.body}`);
 58:     }
 59: 
 60:     await new Promise<void>((resolve) => setTimeout(resolve, 0));
 61: 
 62:     const headRes = await client.head(remoteFile);
 63:     manifest.lastBackupUploadMs = Date.now();
 64:     manifest.lastBackupEtag = safeTrim(headRes.headers['etag'] ?? '');
 65:     await this.store.saveManifestJson(manifest.toJSON());
 66: 
 67:     return WebDavSyncResult.ok('备份已上传');
 68:   }
