 70:   async downloadBackupPlain(
 71:     client: IWebDavBackend,
 72:     settings: WebDavSettings,
 73:     manifest: WebDavManifest,
 74:     remoteFile: string,
 75:     legacyRemoteFile: string,
 76:     force: boolean
 77:   ): Promise<WebDavBackupPlainResult> {
 78:     let targetFile = remoteFile;
 79:     
 80:     if (!force) {
 81:       let headRes = await client.head(targetFile);
 82:       if (headRes.statusCode === 404) {
 83:         const legacyHead = await client.head(legacyRemoteFile);
 84:         if (legacyHead.statusCode !== 404) {
 85:           targetFile = legacyRemoteFile;
 86:           headRes = legacyHead;
 87:         }
 88:       }
 89:       
 90:       const conflict = WebDavConflictResolver.checkBackupRestore(headRes, manifest, force);
 91:       if (conflict) {
 92:         // Special handling for "IDLE" status result from resolver which means we should stop but it's not an error
 93:         // But here we need to return WebDavBackupPlainResult
 94:         return new WebDavBackupPlainResult(conflict, '');
 95:       }
 96:     }
 97: 
 98:     const snapshot = await this.syncManager.exportData();
 99:     if (snapshot.success) {
100:       await this.store.saveSnapshotJson(snapshot.data);
101:     }
102: 
103:     const getRes = await client.get(targetFile);
104:     if (getRes.statusCode < 200 || getRes.statusCode >= 300) {
105:       return new WebDavBackupPlainResult(
106:         WebDavSyncResult.fail('下载失败', `GET ${getRes.statusCode}: ${getRes.body}`),
107:         ''
108:       );
109:     }
110: 
111:     // Bug fix: 使用 TaskPool 在后台线程解密，避免阻塞主线程
112:     let plain: string;
113:     try {
114:       const decryptParams: DecryptTaskParams = {
115:         encryptedData: getRes.body,
116:         syncPassword: settings.syncPassword
117:       };
118:       const decryptResult = await taskpool.execute(new taskpool.Task(executeDecrypt, decryptParams)) as DecryptTaskResult;
119:       
120:       if (!decryptResult.success) {
121:         return new WebDavBackupPlainResult(WebDavSyncResult.fail('解密失败', decryptResult.detail), '');
122:       }
123:       plain = decryptResult.data;
124:     } catch (ce) {
125:       const msg = ce instanceof Error ? ce.message : String(ce);
126:       return new WebDavBackupPlainResult(WebDavSyncResult.fail('解密失败', msg), '');
127:     }
128: 
129:     return new WebDavBackupPlainResult(WebDavSyncResult.ok('已下载云端备份'), plain);
130:   }
