152:       
153:       const conflict = WebDavConflictResolver.checkBackupRestore(headRes, manifest, force);
154:       if (conflict) {
155:         return conflict;
156:       }
157:     }
158: 
159:     // Snapshot local data before import
160:     const snapshot = await this.syncManager.exportData();
161:     if (snapshot.success) {
162:       await this.store.saveSnapshotJson(snapshot.data);
163:     }
164: 
165:     const getRes = await client.get(targetFile);
166:     if (getRes.statusCode < 200 || getRes.statusCode >= 300) {
167:       return WebDavSyncResult.fail('下载失败', `GET ${getRes.statusCode}: ${getRes.body}`);
168:     }
169: 
170:     // Bug fix: 使用 TaskPool 在后台线程解密，避免阻塞主线程
171:     let plain: string;
172:     try {
173:       const decryptParams: DecryptTaskParams = {
174:         encryptedData: getRes.body,
175:         syncPassword: settings.syncPassword
176:       };
177:       const decryptResult = await taskpool.execute(new taskpool.Task(executeDecrypt, decryptParams)) as DecryptTaskResult;
178:       
179:       if (!decryptResult.success) {
180:         return WebDavSyncResult.fail('解密失败', decryptResult.detail);
