190:       return WebDavSyncResult.fail('导入失败', importRes.errors.join('; '));
191:     }
192: 
193:     return WebDavSyncResult.ok(`恢复完成：导入 ${importRes.imported}，更新 ${importRes.updated}`);
194:   }
