 164:   private requireConfigured(): WebDavSyncResult | null {
 165:     if (safeTrim(this.settings.endpoint).length === 0) {
 166:       return WebDavSyncResult.fail('未配置 WebDAV 地址', 'WebDAV endpoint is empty');
 167:     }
 168:     if (safeTrim(this.settings.username).length === 0 || safeTrim(this.settings.password).length === 0) {
 169:       return WebDavSyncResult.fail('未配置 WebDAV 账号', 'WebDAV username/password is empty');
 170:     }
 171:     if (safeTrim(this.settings.syncPassword).length < 4) {
 172:       return WebDavSyncResult.fail('同步密码过短', 'Sync password is too short');
 173:     }
 174:     return null;
 175:   }
 176: 
 177:   private createClient(): IWebDavBackend {
 178:     return new WebDavClient(
 179:       this.settings.endpoint,
 180:       this.settings.username,
 181:       this.settings.password
 182:     );
 183:   }
 184: 
 185:   private rootPath(...parts: string[]): string {
 186:     const base = normalizeRoot(this.settings.remoteRoot);
 187:     let p = base;
 188:     for (const part of parts) {
 189:       const clean = part.replace(/^\/+|\/+$/g, '');
 190:       if (clean.length > 0) {
 191:         p = `${p}/${clean}`;
 192:       }
 193:     }
 194:     return p;
 195:   }
 196: 
 197:   private sanitizePrefix(remoteRoot: string): string {
 198:     const raw = remoteRoot.replace(/^\/+/, '').replace(/\/+$/g, '');
 199:     const replaced = raw.replace(/\/+/g, '_').replace(/[^0-9a-zA-Z_-]+/g, '_');
 200:     const trimmed = replaced.replace(/^_+|_+$/g, '');
 201:     const out = trimmed.length > 0 ? trimmed : 'weiyu_vignette';
 202:     return out.length > 64 ? out.slice(0, 64) : out;
 203:   }
 204: 
 205:   private composeRemotePath(base: string, prefix: string, fileName: string): string {
 206:     const b = base.replace(/\/+$/g, '') || '/';
 207:     const name = prefix.length > 0 ? `${prefix}${fileName}` : fileName;
 208:     if (b === '/') {
 209:       return `/${name}`;
 210:     }
 211:     return `${b}/${name}`;
 212:   }
 213: 
 214:   private backupFilePath(): string {
 215:     return this.composeRemotePath(this.remoteLayoutBase, this.remoteLayoutPrefix, BACKUP_FILE_NAME);
 216:   }
 217: 
 218:   private legacyBackupFilePath(): string {
 219:     return this.rootPath('data', BACKUP_FILE_NAME);
 220:   }
