 237: 
 238:   private isCollectionReachable(statusCode: number): boolean {
 239:     if (statusCode >= 200 && statusCode < 400) {
 240:       return true;
 241:     }
 242:     return statusCode === 405;
 243:   }
 244: 
 245:   private async probeRootWritable(client: IWebDavBackend, prefix: string): Promise<WebDavSyncResult | null> {
 246:     const probeName = `.probe_${Date.now()}.txt`;
 247:     const probePath = this.composeRemotePath('/', prefix, probeName);
 248:     const putRes = await client.put(probePath, 'probe', 'text/plain');
 249:     if (putRes.statusCode >= 200 && putRes.statusCode < 300) {
 250:       await client.delete(probePath);
 251:       return null;
 252:     }
 253:     if (putRes.statusCode === 401 || putRes.statusCode === 403) {
 254:       const msg = putRes.statusCode === 401 ? '鉴权失败（可能需要应用专用密码）' : '根目录权限不足，无法使用根目录前缀模式';
 255:       return WebDavSyncResult.fail('WebDAV 连接失败', `STEP endpoint PUT ${putRes.statusCode}: ${msg}；请在 WebDAV 端创建 ${this.settings.remoteRoot} 或填写一个已存在且有权限的远端目录`);
 256:     }
 257:     if (putRes.statusCode === 409) {
 258:       return WebDavSyncResult.fail('WebDAV 连接失败', `STEP endpoint PUT 409: 路径不存在（AncestorNotFound）；请检查 WebDAV 地址是否指向可用的根目录（例如以 /dav/ 结尾），或先在 WebDAV 端创建 ${this.settings.remoteRoot}`);
 259:     }
 260:     return WebDavSyncResult.fail('WebDAV 连接失败', `STEP endpoint PUT ${putRes.statusCode}: ${putRes.body}`);
 261:   }
 262: 
 263:   private async probeCollectionWritable(client: IWebDavBackend, base: string): Promise<WebDavSyncResult | null> {
 264:     const probeName = `.probe_${Date.now()}.txt`;
 265:     const probePath = this.composeRemotePath(base, '', probeName);
 266:     const putRes = await client.put(probePath, 'probe', 'text/plain');
 267:     if (putRes.statusCode >= 200 && putRes.statusCode < 300) {
 268:       await client.delete(probePath);
 269:       return null;
 270:     }
 271:     if (putRes.statusCode === 401 || putRes.statusCode === 403) {
 272:       const msg = putRes.statusCode === 401 ? '鉴权失败（可能需要应用专用密码）' : '权限不足（目录可能不可写）';
 273:       return WebDavSyncResult.fail('WebDAV 连接失败', `STEP remoteRoot PUT ${putRes.statusCode}: ${msg}`);
 274:     }
 275:     if (putRes.statusCode === 404) {
 276:       return WebDavSyncResult.fail('WebDAV 连接失败', `STEP remoteRoot PUT 404: 远端目录不存在或不可用，请先创建 ${this.settings.remoteRoot}`);
 277:     }
 278:     if (putRes.statusCode === 409) {
 279:       return WebDavSyncResult.fail('WebDAV 连接失败', `STEP remoteRoot PUT 409: 路径不存在（AncestorNotFound）；请先创建 ${this.settings.remoteRoot}`);
 280:     }
 281:     return WebDavSyncResult.fail('WebDAV 连接失败', `STEP remoteRoot PUT ${putRes.statusCode}: ${putRes.body}`);
 282:   }
 283: 
 284:   private async preflightRemoteRoot(client: IWebDavBackend): Promise<WebDavSyncResult | null> {
 285:     const key = `${safeTrim(this.settings.endpoint)}|${safeTrim(this.settings.remoteRoot)}`;
 286:     if (this.remoteLayoutKey === key) {
 287:       return null;
 288:     }
 289: 
 290:     const remoteRoot = normalizeRoot(this.settings.remoteRoot);
 291:     if (remoteRoot === '/') {
 292:       this.remoteLayoutKey = key;
 293:       this.remoteLayoutBase = '/';
 294:       this.remoteLayoutPrefix = '';
 295:       return null;
 296:     }
 297: 
 298:     const rootHead = await client.head(remoteRoot);
 299:     if (this.isCollectionReachable(rootHead.statusCode)) {
 300:       this.remoteLayoutKey = key;
 301:       this.remoteLayoutBase = remoteRoot;
 302:       this.remoteLayoutPrefix = '';
 303:       return null;
 304:     }
 305: 
 306:     // 目录不存在，尝试创建
 307:     if (rootHead.statusCode === 404) {
 308:       console.info(`[WebDavSyncManager] Remote directory ${remoteRoot} not found, trying to create it`);
 309:       const createResult = await this.ensureRemoteDirectory(client, remoteRoot);
 310:       if (createResult !== null) {
 311:         return createResult;
 312:       }
 313:       // 创建成功，重新检查
 314:       const recheckHead = await client.head(remoteRoot);
 315:       if (this.isCollectionReachable(recheckHead.statusCode)) {
 316:         this.remoteLayoutKey = key;
 317:         this.remoteLayoutBase = remoteRoot;
 318:         this.remoteLayoutPrefix = '';
 319:         return null;
 320:       }
 321:     }
 322: 
 323:     const probeRemoteRoot = await this.probeCollectionWritable(client, remoteRoot);
 324:     if (probeRemoteRoot === null) {
 325:       this.remoteLayoutKey = key;
 326:       this.remoteLayoutBase = remoteRoot;
 327:       this.remoteLayoutPrefix = '';
 328:       return null;
 329:     }
 330: 
 331:     if (this.settings.requireRemoteRootExists) {
 332:       return probeRemoteRoot;
 333:     }
 334: 
 335:     const prefix = `${this.sanitizePrefix(remoteRoot)}__`;
 336:     const probe = await this.probeRootWritable(client, prefix);
 337:     if (probe !== null) {
 338:       return probe;
 339:     }
 340:     this.remoteLayoutKey = key;
 341:     this.remoteLayoutBase = '/';
 342:     this.remoteLayoutPrefix = prefix;
 343:     return null;
 344:   }
 345: 
 346:   /**
 347:    * 确保远程目录存在，如果不存在则创建
 348:    */
 349:   private async ensureRemoteDirectory(client: IWebDavBackend, path: string): Promise<WebDavSyncResult | null> {
 350:     try {
 351:       // 递归创建父目录
 352:       const lastSlash = path.lastIndexOf('/');
 353:       if (lastSlash > 0) {
 354:         const parent = path.substring(0, lastSlash);
 355:         if (parent.length > 0 && parent !== '/') {
 356:           const parentHead = await client.head(parent);
 357:           if (parentHead.statusCode === 404) {
 358:             const parentResult = await this.ensureRemoteDirectory(client, parent);
 359:             if (parentResult !== null) {
 360:               return parentResult;
 361:             }
 362:           }
 363:         }
 364:       }
 365: 
 366:       // 创建当前目录（通过 PUT 一个 .keep 文件）
 367:       const keepFile = path.endsWith('/') ? `${path}.keep` : `${path}/.keep`;
 368:       const putRes = await client.put(keepFile, 'keep', 'text/plain');
 369:       if (putRes.statusCode >= 200 && putRes.statusCode < 300) {
 370:         console.info(`[WebDavSyncManager] Created remote directory: ${path}`);
 371:         return null;
 372:       }
 373:       if (putRes.statusCode === 401 || putRes.statusCode === 403) {
 374:         return WebDavSyncResult.fail('创建目录失败', `权限不足: ${putRes.statusCode}`);
 375:       }
 376:       return WebDavSyncResult.fail('创建目录失败', `PUT ${putRes.statusCode}: ${putRes.body}`);
 377:     } catch (e) {
 378:       const msg = e instanceof Error ? e.message : String(e);
 379:       return WebDavSyncResult.fail('创建目录失败', msg);
 380:     }
 381:   }
 382: 
 383:   async testConnection(): Promise<WebDavSyncResult> {
 384:     const missing = this.requireConfigured();
 385:     if (missing !== null) return missing;
 386: 
 387:     this.status = WebDavSyncStatus.TESTING;
 388:     try {
 389:       const client = this.createClient();
 390:       const remoteRoot = normalizeRoot(this.settings.remoteRoot);
 391:       if (remoteRoot !== '/') {
 392:         const rootHead = await client.head(remoteRoot);
 393:         if (this.isCollectionReachable(rootHead.statusCode)) {
 394:           this.remoteLayoutKey = `${safeTrim(this.settings.endpoint)}|${safeTrim(this.settings.remoteRoot)}`;
 395:           this.remoteLayoutBase = remoteRoot;
 396:           this.remoteLayoutPrefix = '';
 397:           this.status = WebDavSyncStatus.IDLE;
 398:           return WebDavSyncResult.ok('WebDAV 连接成功');
 399:         }
 400: 
 401:         const probeRemoteRoot = await this.probeCollectionWritable(client, remoteRoot);
 402:         if (probeRemoteRoot === null) {
 403:           this.remoteLayoutKey = `${safeTrim(this.settings.endpoint)}|${safeTrim(this.settings.remoteRoot)}`;
 404:           this.remoteLayoutBase = remoteRoot;
 405:           this.remoteLayoutPrefix = '';
 406:           this.status = WebDavSyncStatus.IDLE;
 407:           return WebDavSyncResult.ok('WebDAV 连接成功');
 408:         }
 409: 
 410:         if (this.settings.requireRemoteRootExists) {
 411:           this.status = WebDavSyncStatus.ERROR;
 412:           return probeRemoteRoot;
 413:         }
 414: 
 415:         const prefix = `${this.sanitizePrefix(remoteRoot)}__`;
 416:         const probe = await this.probeRootWritable(client, prefix);
 417:         if (probe !== null) {
 418:           this.status = WebDavSyncStatus.ERROR;
 419:           return probe;
 420:         }
 421:         this.remoteLayoutKey = `${safeTrim(this.settings.endpoint)}|${safeTrim(this.settings.remoteRoot)}`;
 422:         this.remoteLayoutBase = '/';
 423:         this.remoteLayoutPrefix = prefix;
 424:         this.status = WebDavSyncStatus.IDLE;
 425:         return WebDavSyncResult.ok('WebDAV 连接成功（已使用根目录前缀模式）');
 426:       }
 427: 
 428:       const probe = await this.probeRootWritable(client, '');
 429:       if (probe !== null) {
 430:         this.status = WebDavSyncStatus.ERROR;
 431:         return probe;
 432:       }
 433:       this.remoteLayoutKey = `${safeTrim(this.settings.endpoint)}|${safeTrim(this.settings.remoteRoot)}`;
 434:       this.remoteLayoutBase = '/';
 435:       this.remoteLayoutPrefix = '';
 436:       this.status = WebDavSyncStatus.IDLE;
 437:       return WebDavSyncResult.ok('WebDAV 连接成功');
 438:     } catch (e) {
 439:       this.status = WebDavSyncStatus.ERROR;
 440:       const msg = e instanceof Error ? e.message : String(e);
 441:       return WebDavSyncResult.fail('WebDAV 连接失败', msg);
 442:     }
 443:   }
