 445:   // ==================== Backup / Restore ====================
 446: 
 447:   async backupToCloud(): Promise<WebDavSyncResult> {
 448:     const missing = this.requireConfigured();
 449:     if (missing !== null) return missing;
 450: 
 451:     this.status = WebDavSyncStatus.SYNCING;
 452:     try {
 453:       const client = this.createClient();
 454:       const preflight = await this.preflightRemoteRoot(client);
 455:       if (preflight !== null) {
 456:         this.status = WebDavSyncStatus.ERROR;
 457:         return preflight;
 458:       }
 459: 
 460:       const result = await this.backupManager.backupToCloud(
 461:         client,
 462:         this.settings,
 463:         this.manifest,
 464:         this.backupFilePath()
 465:       );
 466:       this.status = result.success ? WebDavSyncStatus.IDLE : WebDavSyncStatus.ERROR;
 467:       return result;
