 670:   // ==================== Incremental Sync ====================
 671: 
 672:   async syncIncremental(): Promise<WebDavSyncResult> {
 673:     console.info('[WebDavSyncManager] ==== Starting incremental sync ====');
 674:     const syncStartMs = Date.now();
 675:     
 676:     const missing = this.requireConfigured();
 677:     if (missing !== null) {
 678:       console.error('[WebDavSyncManager] Sync failed: not configured');
 679:       return missing;
 680:     }
 681: 
 682:     // 检查是否已经在同步中
 683:     if (this.status === WebDavSyncStatus.SYNCING) {
 684:       console.warn('[WebDavSyncManager] Sync already in progress');
 685:       return WebDavSyncResult.fail('同步操作正在进行中', '请等待当前同步完成后再试');
 686:     }
 687: 
 688:     this.status = WebDavSyncStatus.SYNCING;
 689:     console.info('[WebDavSyncManager] Sync status set to SYNCING');
 690: 
 691:     // 先确保远程目录存在
 692:     const client = this.createClient();
 693:     const preflight = await this.preflightRemoteRoot(client);
 694:     if (preflight !== null) {
 695:       this.status = WebDavSyncStatus.ERROR;
 696:       console.error(`[WebDavSyncManager] Preflight check failed: ${preflight.message}`);
 697:       return preflight;
 698:     }
 699: 
 700:     // yield 给 UI 线程
 701:     await new Promise<void>((resolve) => setTimeout(resolve, 0));
 702: 
 703:     try {
 704:       const syncManager = DataSyncManager.getInstance();
 705:       const dbManager = DBManager.getInstance();
 706: 
 707:       // ========== 步骤 1: 单词下载 ==========
 708:       console.info('[WebDavSyncManager] ===== Step 1/4: Download words delta =====');
 709:       const step1StartMs = Date.now();
 710:       const downloadParams: DownloadTaskParams = {
 711:         endpoint: this.settings.endpoint,
 712:         username: this.settings.username,
 713:         password: this.settings.password,
 714:         syncPassword: this.settings.syncPassword,
 715:         remoteRoot: this.settings.remoteRoot,
 716:         manifestJson: this.manifest.toJSON(),
 717:         remoteFile: this.wordsDeltaFilePath()
 718:       };
 719:       const downloadResult = await this.executeTaskWithFallback<DownloadTaskParams, DownloadTaskResult>(executeDownload, downloadParams);
 720:       const step1Ms = Date.now() - step1StartMs;
 721: 
 722:       if (!downloadResult.success) {
 723:         console.error(`[WebDavSyncManager] Step 1 failed: ${downloadResult.detail}`);
 724:         return WebDavSyncResult.fail('增量同步失败（单词下载）', downloadResult.detail);
 725:       }
 726: 
 727:       console.info(`[WebDavSyncManager] Step 1 complete ms=${step1Ms} data_length=${downloadResult.data.length}`);
 728: 
 729:       // yield 给 UI 线程
 730:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
 731: 
 732:       // 如果有数据，导入单词
 733:       if (downloadResult.data.length > 0) {
 734:         console.info('[WebDavSyncManager] Importing downloaded words');
 735:         const importResult = await syncManager.importIncremental(downloadResult.data);
 736:         if (importResult.hasErrors()) {
 737:           console.error(`[WebDavSyncManager] Import failed: ${importResult.errors.join('; ')}`);
 738:           return WebDavSyncResult.fail('增量同步失败（单词下载）', importResult.errors.join('; '));
 739:         }
 740:         console.info('[WebDavSyncManager] Import complete');
 741:       } else {
 742:         console.info('[WebDavSyncManager] No words to import');
 743:       }
 744: 
 745:       // yield 给 UI 线程
 746:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
 747: 
 748:       // ========== 步骤 2: 单词上传 ==========
 749:       console.info('[WebDavSyncManager] ===== Step 2/4: Upload words delta =====');
 750:       const step2StartMs = Date.now();
 751:       const exportResult = await syncManager.exportIncremental(this.manifest.lastWordsSyncMs, false);
 752:       if (!exportResult.success) {
 753:         console.error(`[WebDavSyncManager] Step 2 export failed: ${exportResult.error}`);
 754:         return WebDavSyncResult.fail('增量同步失败（单词上传）', exportResult.error);
 755:       }
 756: 
 757:       console.info(`[WebDavSyncManager] Step 2 export complete data_length=${exportResult.data.length}`);
 758: 
 759:       // yield 给 UI 线程
 760:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
 761: 
 762:       if (exportResult.data.length > 0) {
 763:         console.info('[WebDavSyncManager] Uploading words to cloud');
 764:         // 加密和上传数据（在 TaskPool 中执行，避免阻塞 UI）
 765:         const uploadParams: UploadTaskWithEncryptParams = {
 766:           endpoint: this.settings.endpoint,
 767:           username: this.settings.username,
 768:           password: this.settings.password,
 769:           syncPassword: this.settings.syncPassword,
 770:           remoteRoot: this.settings.remoteRoot,
 771:           manifestJson: this.manifest.toJSON(),
 772:           remoteFile: this.wordsDeltaFilePath(),
 773:           plainData: exportResult.data
 774:         };
 775:         const uploadResult = await this.executeTaskWithFallback<UploadTaskWithEncryptParams, UploadTaskResult>(executeUploadWithEncrypt, uploadParams);
 776: 
 777:         if (!uploadResult.success) {
 778:           console.error(`[WebDavSyncManager] Step 2 upload failed: ${uploadResult.detail}`);
 779:           return WebDavSyncResult.fail('增量同步失败（单词上传）', uploadResult.detail);
 780:         }
 781:         const step2Ms = Date.now() - step2StartMs;
 782:         console.info(`[WebDavSyncManager] Step 2 complete ms=${step2Ms}`);
 783:       } else {
 784:         console.info('[WebDavSyncManager] No words to upload, skipping step 2');
 785:       }
 786: 
 787:       // yield 给 UI 线程
 788:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
 789: 
 790:       // ========== 步骤 3: 事件下载 ==========
 791:       console.info('[WebDavSyncManager] ===== Step 3/4: Download events =====');
 792:       const step3StartMs = Date.now();
 793:       const eventsDownloadParams: DownloadTaskParams = {
 794:         endpoint: this.settings.endpoint,
 795:         username: this.settings.username,
 796:         password: this.settings.password,
 797:         syncPassword: this.settings.syncPassword,
 798:         remoteRoot: this.settings.remoteRoot,
 799:         manifestJson: this.manifest.toJSON(),
 800:         remoteFile: this.eventsFilePath()
 801:       };
 802:       const eventsDownloadResult = await this.executeTaskWithFallback<DownloadTaskParams, DownloadTaskResult>(executeDownload, eventsDownloadParams);
 803: 
 804:       // Bug fix: 当 MAC 校验失败时，不中止同步，而是跳过事件下载并继续上传本地数据覆盖云端
 805:       let eventsDownloadSkipped = false;
 806:       if (!eventsDownloadResult.success) {
 807:         // 检查是否为 MAC 校验失败或密码错误
 808:         if (eventsDownloadResult.detail.includes('MAC verification failed') || 
 809:             eventsDownloadResult.detail.includes('同步密码错误') ||
 810:             eventsDownloadResult.detail.includes('云端数据已损坏')) {
 811:           console.warn(`[WebDavSyncManager] Step 3 MAC verification failed, skipping download and will re-upload: ${eventsDownloadResult.detail}`);
 812:           eventsDownloadSkipped = true;
 813:         } else {
 814:           // 其他错误仍然返回失败
 815:           console.error(`[WebDavSyncManager] Step 3 failed: ${eventsDownloadResult.detail}`);
 816:           return WebDavSyncResult.fail('增量同步失败（事件下载）', eventsDownloadResult.detail);
 817:         }
 818:       }
 819: 
 820:       if (!eventsDownloadSkipped) {
 821:         const step3Ms = Date.now() - step3StartMs;
 822:         console.info(`[WebDavSyncManager] Step 3 complete ms=${step3Ms} data_length=${eventsDownloadResult.data.length}`);
 823: 
 824:         // yield 给 UI 线程
 825:         await new Promise<void>((resolve) => setTimeout(resolve, 0));
 826: 
 827:         // 如果有数据，导入事件
 828:         if (eventsDownloadResult.data.length > 0) {
 829:           console.info('[WebDavSyncManager] Importing review events');
 830:           const events = this.parseEventsJsonl(eventsDownloadResult.data);
 831:           console.info(`[WebDavSyncManager] Parsed ${events.length} events, inserting to database`);
 832:           await dbManager.insertReviewEvents(events);
 833:           console.info('[WebDavSyncManager] Events inserted successfully');
 834:         } else {
 835:           console.info('[WebDavSyncManager] No events to import');
 836:         }
 837:       } else {
 838:         console.info('[WebDavSyncManager] Step 3 skipped due to MAC verification failure');
 839:       }
 840: 
 841:       // yield 给 UI 线程
 842:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
 843: 
 844:       // ========== 步骤 4: 事件上传 ==========
 845:       console.info('[WebDavSyncManager] ===== Step 4/4: Upload events =====');
 846:       const step4StartMs = Date.now();
 847:       console.info(`[WebDavSyncManager] Fetching events after timestamp ${this.manifest.lastEventsSyncMs}`);
 848:       const events = await dbManager.getReviewEventsAfter(this.manifest.lastEventsSyncMs);
 849:       console.info(`[WebDavSyncManager] Found ${events.length} events to upload`);
 850: 
 851:       // yield 给 UI 线程
 852:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
 853: 
 854:       if (events.length > 0) {
 855:         console.info('[WebDavSyncManager] Serializing events');
 856:         const eventsJsonl = this.serializeEventsJsonl(events);
 857:         console.info(`[WebDavSyncManager] Serialized to ${eventsJsonl.length} chars`);
 858: 
 859:         // yield 给 UI 线程
 860:         await new Promise<void>((resolve) => setTimeout(resolve, 0));
 861: 
 862:         // 加密和上传数据（在 TaskPool 中执行，避免阻塞 UI）
 863:         const eventsUploadParams: UploadTaskWithEncryptParams = {
 864:           endpoint: this.settings.endpoint,
 865:           username: this.settings.username,
 866:           password: this.settings.password,
 867:           syncPassword: this.settings.syncPassword,
 868:           remoteRoot: this.settings.remoteRoot,
 869:           manifestJson: this.manifest.toJSON(),
 870:           remoteFile: this.eventsFilePath(),
 871:           plainData: eventsJsonl
 872:         };
 873:         const eventsUploadResult = await this.executeTaskWithFallback<UploadTaskWithEncryptParams, UploadTaskResult>(executeUploadWithEncrypt, eventsUploadParams);
 874: 
 875:         if (!eventsUploadResult.success) {
 876:           console.error(`[WebDavSyncManager] Step 4 upload failed: ${eventsUploadResult.detail}`);
 877:           return WebDavSyncResult.fail('增量同步失败（事件上传）', eventsUploadResult.detail);
 878:         }
 879:         const step4Ms = Date.now() - step4StartMs;
 880:         console.info(`[WebDavSyncManager] Step 4 complete ms=${step4Ms}`);
 881:       } else {
 882:         console.info('[WebDavSyncManager] No events to upload, skipping step 4');
 883:       }
 884: 
 885:       const totalSyncMs = Date.now() - syncStartMs;
 886:       console.info(`[WebDavSyncManager] ==== Sync completed successfully total_ms=${totalSyncMs} ====`);
 887:       
 888:       // 如果事件下载被跳过（因为 MAC 校验失败），提示用户事件已重新上传
 889:       if (eventsDownloadSkipped) {
 890:         return WebDavSyncResult.ok('同步完成（已重新上传事件数据覆盖云端损坏文件）');
 891:       }
 892:       return WebDavSyncResult.ok('同步完成');
 893:     } catch (e) {
 894:       const msg = e instanceof Error ? e.message : String(e);
 895:       const stack = e instanceof Error ? e.stack : '';
 896:       console.error(`[WebDavSyncManager] Sync failed with exception: ${msg}`);
 897:       if (stack) {
 898:         console.error(`[WebDavSyncManager] Stack trace: ${stack}`);
 899:       }
 900:       return WebDavSyncResult.fail('增量同步失败', msg);
 901:     } finally {
 902:       // 确保状态总是重置为 IDLE
 903:       this.status = WebDavSyncStatus.IDLE;
 904:       console.info('[WebDavSyncManager] Sync status reset to IDLE');
 905:     }
 906:   }
