170:         const location = resHeaders['location'] ?? '';
171:         console.info(`[WebDAV] ${String(method)} ${url} - ${statusCode} (redirect: ${location}) in ${elapsed}ms`);
172:         if (location.length > 0) {
173:           return this.requestWithRedirect(method, location, headers, body, redirectsLeft - 1, requestId);
174:         }
175:       }
176:       console.info(`[WebDAV] ${String(method)} ${url} - ${statusCode} in ${elapsed}ms`);
177:       return { statusCode, headers: resHeaders, body: bodyStr };
178:     } catch (e) {
179:       request.destroy();
