349:   private async ensureRemoteDirectory(client: IWebDavBackend, path: string): Promise<WebDavSyncResult | null> {
350:     try {
351:       // 递归创建父目录
352:       const lastSlash = path.lastIndexOf('/');
353:       if (lastSlash > 0) {
354:         const parent = path.substring(0, lastSlash);
355:         if (parent.length > 0 && parent !== '/') {
356:           const parentHead = await client.head(parent);
357:           if (parentHead.statusCode === 404) {
358:             const parentResult = await this.ensureRemoteDirectory(client, parent);
359:             if (parentResult !== null) {
360:               return parentResult;
361:             }
362:           }
363:         }
364:       }
365: 
366:       // 创建当前目录（通过 PUT 一个 .keep 文件）
367:       const keepFile = path.endsWith('/') ? `${path}.keep` : `${path}/.keep`;
368:       const putRes = await client.put(keepFile, 'keep', 'text/plain');
369:       if (putRes.statusCode >= 200 && putRes.statusCode < 300) {
370:         console.info(`[WebDavSyncManager] Created remote directory: ${path}`);
371:         return null;
372:       }
373:       if (putRes.statusCode === 401 || putRes.statusCode === 403) {
374:         return WebDavSyncResult.fail('创建目录失败', `权限不足: ${putRes.statusCode}`);
375:       }
376:       return WebDavSyncResult.fail('创建目录失败', `PUT ${putRes.statusCode}: ${putRes.body}`);
377:     } catch (e) {
378:       const msg = e instanceof Error ? e.message : String(e);
379:       return WebDavSyncResult.fail('创建目录失败', msg);
380:     }
381:   }
